mapper.select:
SELECT * FROM ( SELECT ROWNUM AS RNUM, A.* FROM ( SELECT /*+ INDEX(O IDX_ORD_DATE) */ O.ORDER_ID, C.CUSTOMER_NAME, TO_CHAR(O.ORDER_DATE, 'YYYY-MM-DD') AS ORDER_DATE, FN_FORMAT_AMOUNT(O.TOTAL_AMOUNT) AS TOTAL_AMOUNT, O.ORDER_STATUS, NVL(O.PAYMENT_METHOD, '-') AS PAYMENT_METHOD, (SELECT COUNT(*) FROM ORDER_ITEMS OI WHERE OI.ORDER_ID = O.ORDER_ID) AS ITEM_COUNT FROM ORDERS O JOIN CUSTOMERS C ON O.CUSTOMER_ID = C.CUSTOMER_ID WHERE 1 = 1
AND O.ORDER_DATE >= TO_DATE(#{startDate}, 'YYYY-MM-DD')
AND O.ORDER_DATE <= TO_DATE(#{endDate}, 'YYYY-MM-DD')
AND O.ORDER_STATUS = #{orderStatus}
AND O.CUSTOMER_ID = #{customerId}
ORDER BY O.ORDER_DATE DESC, O.ORDER_ID DESC ) A WHERE ROWNUM <= #{endRow} ) WHERE RNUM >= #{startRow}

mapper.update:
UPDATE ORDERS
SET TOTAL_AMOUNT = (
        SELECT NVL(SUM(QUANTITY * UNIT_PRICE - NVL(DISCOUNT_AMT, 0)), 0)
        FROM ORDER_ITEMS
        WHERE ORDER_ID = #{orderId}
    ),
    TAX_AMOUNT = (
        SELECT ROUND(NVL(SUM(QUANTITY * UNIT_PRICE - NVL(DISCOUNT_AMT, 0)), 0) * 0.1, 2)
        FROM ORDER_ITEMS
        WHERE ORDER_ID = #{orderId}
    ),
    UPD_DATE = SYSTIMESTAMP
WHERE ORDER_ID = #{orderId}

mapper.select:
SELECT NVL(TO_CHAR(ORDER_DATE, 'YYYY-MM'), '합계') AS SALES_MONTH, COUNT(*) AS ORDER_COUNT, FN_FORMAT_AMOUNT(SUM(TOTAL_AMOUNT)) AS TOTAL_SALES, FN_FORMAT_AMOUNT(ROUND(AVG(TOTAL_AMOUNT), 2)) AS AVG_ORDER, FN_FORMAT_AMOUNT(MAX(TOTAL_AMOUNT)) AS MAX_ORDER, FN_FORMAT_AMOUNT(MIN(TOTAL_AMOUNT)) AS MIN_ORDER FROM ORDERS WHERE ORDER_STATUS NOT IN ('CANCELLED')
AND EXTRACT(YEAR FROM ORDER_DATE) = #{year}
GROUP BY ROLLUP(TO_CHAR(ORDER_DATE, 'YYYY-MM')) ORDER BY SALES_MONTH

SELECT ORDER_ID, CUSTOMER_NAME, ORDER_DATE, TOTAL_AMOUNT, ROW_NUMBER() OVER (ORDER BY TOTAL_AMOUNT DESC) AS RN, RANK() OVER (ORDER BY TOTAL_AMOUNT DESC) AS SALES_RANK, LAG(TOTAL_AMOUNT) OVER (ORDER BY ORDER_DATE) AS PREV_ORDER_AMT, LEAD(TOTAL_AMOUNT) OVER (ORDER BY ORDER_DATE) AS NEXT_ORDER_AMT, SUM(TOTAL_AMOUNT) OVER (ORDER BY ORDER_DATE ROWS UNBOUNDED PRECEDING) AS RUNNING_TOTAL, ROUND(RATIO_TO_REPORT(TOTAL_AMOUNT) OVER () * 100, 2) AS SALES_PCT FROM ( SELECT O.ORDER_ID, C.CUSTOMER_NAME, TO_CHAR(O.ORDER_DATE, 'YYYY-MM-DD') AS ORDER_DATE, O.TOTAL_AMOUNT FROM ORDERS O JOIN CUSTOMERS C ON O.CUSTOMER_ID = C.CUSTOMER_ID WHERE O.ORDER_STATUS = 'DELIVERED'
AND EXTRACT(YEAR FROM O.ORDER_DATE) = #{year}
)
